export const initialConfig={board:'am5',cpu:'cpu5',ram:'ddr5',ssd:'nvme',gpu:'rtx4060'};
export function evaluate(config){
 const get=k=>catalog[k].options.find(o=>o.id===config[k]);
 const b=get('board'),c=get('cpu'),r=get('ram'),s=get('ssd'),g=get('gpu');
 if(!b||!c||!r||!s||!g)throw new Error('Configuración desconocida');
 return [
 {name:'Socket del procesador',status:b.socket===c.socket?'pass':'fail',detail:`La placa declara ${b.socket} y el procesador ${c.socket}. ${b.socket===c.socket?'Coinciden en socket; todavía falta verificar soporte del modelo y BIOS.':'Los sockets no coinciden.'}`},
 {name:'Generación de memoria',status:b.memory===r.memory?'pass':'fail',detail:`La placa usa ${b.memory} y el kit seleccionado ${r.memory}. ${b.memory===r.memory?'Coinciden en generación.':'Este kit no corresponde a las ranuras de la placa.'}`},
 {name:'Capacidad de memoria',status:r.capacity<=Math.min(b.maxRam,c.maxRam)?'pass':'fail',detail:`Seleccionaste ${r.capacity} GB. La ficha de la placa indica ${b.maxRam} GB y la del procesador ${c.maxRam} GB. Se toma el menor límite; falta verificar el kit exacto y su soporte.`},
 {name:'Protocolo del SSD',status:b.ssd===s.protocol||b.id==='intel'?'pass':'fail',detail:s.protocol==='SATA'?(b.id==='intel'?'El SSD M.2 SATA requiere M2_2 en esta MSI; al usarlo queda deshabilitado SATA8. No corresponde a M2_1.':'Los conectores M.2 de almacenamiento de esta ASUS son PCIe; el perfil M.2 SATA seleccionado no corresponde.'):'El perfil NVMe 2280 coincide con el tipo admitido. Revisá el conector elegido y la fijación en el manual.'},
 {name:'Verificación del equipo completo',status:'unknown',detail:'Información insuficiente: faltan modelos exactos, soporte de BIOS, fuente, dimensiones, cooler y distribución de líneas.'}
 ];
}
export const connectorTypes=['CPU_SOCKET','DIMM_SLOT','PCIe_X16','PCIe_X1','M2_SLOT','SATA_PORT','ATX_POWER','CPU_POWER','FAN_HEADER'];

export function assessPerformance(config,usage){
 const rules=evaluate(config);if(!['general','competitive','visual','creation'].includes(usage))throw new Error('Uso desconocido');
 if(rules.some(r=>r.status==='fail'))return{title:'Resolvé primero las incompatibilidades',detail:'El análisis de rendimiento queda suspendido porque hay componentes que no pueden usarse juntos.',items:[]};
 const cpu=catalog.cpu.options.find(o=>o.id===config.cpu),gpu=catalog.gpu.options.find(o=>o.id===config.gpu),ram=catalog.ram.options.find(o=>o.id===config.ram);
 const priorities={general:'Para uso cotidiano, observá memoria disponible, procesos abiertos y tiempos de respuesta del almacenamiento.',competitive:'Para buscar FPS altos en juegos competitivos, medí tiempos de cuadro y carga de CPU por núcleo junto con el uso de GPU. La media de CPU puede ocultar un hilo saturado.',visual:'En juegos a 1440p y calidad alta, revisá carga de GPU y memoria de video en el juego elegido. Reducir resolución o efectos permite investigar si el límite es gráfico.',creation:'En edición o render, el límite depende del programa, códec, escena y aceleración elegida. Compará el tiempo de la misma tarea y observá CPU, GPU, RAM y disco.'};
 return{title:'Posibles límites a investigar',detail:'Orientación por uso. No hay benchmarks cargados para confirmar un cuello de botella ni calcular un porcentaje.',items:[{title:'Tu combinación',text:`${cpu.name} + ${gpu.name}. La ficha técnica describe capacidades, pero no predice por sí sola el rendimiento conjunto.`},{title:'Qué medir',text:priorities[usage]},{title:ram.capacity<16?'Atención a la memoria disponible':'Memoria y carga de trabajo',text:ram.capacity<16?`${ram.capacity} GB pueden restringir la multitarea o aplicaciones exigentes. Confirmalo observando presión de memoria y paginación.`:`Tenés ${ram.capacity} GB de RAM y ${gpu.vram} GB de VRAM. Compará el consumo de la tarea real con ambas capacidades; no son intercambiables.`}]};
}
